package com.drogaria.backend.service;
import com.drogaria.backend.dto.*; import com.drogaria.backend.entity.Cupom; import com.drogaria.backend.exception.ApiException; import com.drogaria.backend.repository.CupomRepository; import org.springframework.http.HttpStatus; import org.springframework.stereotype.Service; import java.util.List;
@Service public class CupomService { private final CupomRepository r; public CupomService(CupomRepository r){this.r=r;} public List<CupomResponse> listar(){return r.findAll().stream().map(CupomResponse::new).toList();} public CupomResponse buscar(Integer id){return new CupomResponse(r.findById(id).orElseThrow(()->new ApiException("Cupom nao encontrado",HttpStatus.NOT_FOUND)));} public CupomResponse salvar(CupomRequest x){Cupom c=new Cupom(); preencher(c,x); return new CupomResponse(r.save(c));} public CupomResponse atualizar(Integer id,CupomRequest x){Cupom c=r.findById(id).orElseThrow(()->new ApiException("Cupom nao encontrado",HttpStatus.NOT_FOUND));preencher(c,x);return new CupomResponse(r.save(c));} private void preencher(Cupom c,CupomRequest x){if(x.getDesconto().signum()<0)throw new ApiException("Desconto invalido",HttpStatus.BAD_REQUEST);c.setCodigo(x.getCodigo().trim());c.setDesconto(x.getDesconto());c.setRegras(x.getRegras());c.setValidade(x.getValidade());} public void excluir(Integer id){if(!r.existsById(id))throw new ApiException("Cupom nao encontrado",HttpStatus.NOT_FOUND);r.deleteById(id);} }